import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, join, relative, resolve } from "node:path";
import { SLOT_TEXT_MAX_LENGTH } from "@loomcast/contracts";
import { z } from "zod";
import { studioPaths } from "./paths.ts";

// The card registry: `style-library/registry.json` (generated by
// scripts/style-library/build-registry.mjs) joined with each style's `style.json`, which declares
// slot types and character limits that the generated index leaves out.

export type SlotType = "text" | "richtext" | "image";

export interface CardSlot {
  name: string;
  type: SlotType;
  /** The longest text the slot takes: the declared limit, capped by the storyboard contract. */
  maxChars: number;
  note?: string;
}

export interface Card {
  id: string;
  styleId: string;
  tier: string;
  purpose: string;
  /** Absolute path of the card's standalone HTML. */
  file: string;
  slots: CardSlot[];
  /** How long the card may stay on screen, in seconds. */
  duration: { min: number; max: number };
}

export interface Style {
  id: string;
  name: string;
  /** Absolute path of the style folder. */
  dir: string;
  /** Absolute path of the style's `tokens.css`. */
  tokens: string;
  palette: Record<string, string>;
  fonts: Record<string, string>;
  cards: Card[];
}

export interface CardRegistry {
  /** Absolute path of the style library. */
  libraryDir: string;
  styles: Style[];
  getStyle(id: string): Style | undefined;
  getCard(id: string): Card | undefined;
  /** Cards of one style, optionally narrowed to a tier and purpose. */
  findCards(styleId: string, filter?: { tier?: string; purpose?: string }): Card[];
}

const RegistryCardSchema = z.object({
  id: z.string().min(1),
  style: z.string().min(1),
  tier: z.string().min(1),
  purpose: z.string().min(1),
  file: z.string().min(1),
  slots: z.array(z.string().min(1)),
  duration: z.object({ min: z.number().positive(), max: z.number().positive() }),
});

const RegistryFileSchema = z.object({
  styles: z.array(
    z.object({
      id: z.string().min(1),
      name: z.string().min(1),
      folder: z.string().min(1),
      palette: z.record(z.string(), z.string()).optional(),
      fonts: z.record(z.string(), z.string()).optional(),
      cards: z.array(RegistryCardSchema),
    }),
  ),
});

const StyleSlotSchema = z.object({
  name: z.string().min(1),
  type: z.enum(["text", "richtext", "image"]).catch("text"),
  maxChars: z.number().int().positive().optional(),
  note: z.string().optional(),
});

const StyleFileSchema = z.object({
  cards: z.array(
    z.object({
      id: z.string().min(1),
      slots: z.array(z.union([z.string().min(1), StyleSlotSchema])),
    }),
  ),
});

type StyleSlot = z.infer<typeof StyleSlotSchema>;

/** Resolves `path` inside `root`, refusing anything that escapes it. */
function inside(root: string, path: string): string {
  const full = resolve(root, path);
  const rel = relative(root, full);
  if (rel === "" || rel.startsWith("..") || isAbsolute(rel)) {
    throw new Error(`Registry path escapes the style library: ${path}`);
  }
  return full;
}

function readJson(path: string): unknown {
  return JSON.parse(readFileSync(path, "utf8"));
}

/** Slot declarations from a style's `style.json`, keyed by card id. */
function loadStyleSlots(styleDir: string): Map<string, Map<string, StyleSlot>> {
  const byCard = new Map<string, Map<string, StyleSlot>>();
  const path = join(styleDir, "style.json");
  if (!existsSync(path)) return byCard;
  const style = StyleFileSchema.parse(readJson(path));
  for (const card of style.cards) {
    const slots = new Map<string, StyleSlot>();
    for (const slot of card.slots) {
      const declared = typeof slot === "string" ? { name: slot, type: "text" as const } : slot;
      slots.set(declared.name, declared);
    }
    byCard.set(card.id, slots);
  }
  return byCard;
}

export interface LoadRegistryOptions {
  studioRoot?: string;
  /** A style library directory; defaults to the studio's `style-library/`. */
  libraryDir?: string;
}

/** Loads and indexes the card registry. Throws if `registry.json` is missing or malformed. */
export function loadRegistry(options: LoadRegistryOptions = {}): CardRegistry {
  const libraryDir = resolve(options.libraryDir ?? studioPaths(options.studioRoot).styleLibrary);
  const file = RegistryFileSchema.parse(readJson(join(libraryDir, "registry.json")));

  const styles: Style[] = file.styles.map((entry) => {
    const dir = inside(libraryDir, entry.folder);
    const declared = loadStyleSlots(dir);
    const cards = entry.cards.map((card): Card => {
      const slotInfo = declared.get(card.id);
      return {
        id: card.id,
        styleId: card.style,
        tier: card.tier,
        purpose: card.purpose,
        file: inside(libraryDir, card.file),
        duration: { min: card.duration.min, max: card.duration.max },
        slots: card.slots.map((name) => {
          const info = slotInfo?.get(name);
          return {
            name,
            type: info?.type ?? "text",
            maxChars: Math.min(info?.maxChars ?? SLOT_TEXT_MAX_LENGTH, SLOT_TEXT_MAX_LENGTH),
            ...(info?.note ? { note: info.note } : {}),
          };
        }),
      };
    });
    return {
      id: entry.id,
      name: entry.name,
      dir,
      tokens: join(dir, "tokens.css"),
      palette: entry.palette ?? {},
      fonts: entry.fonts ?? {},
      cards,
    };
  });

  const styleIndex = new Map(styles.map((style) => [style.id, style]));
  const cardIndex = new Map(styles.flatMap((style) => style.cards.map((card) => [card.id, card])));

  return {
    libraryDir,
    styles,
    getStyle: (id) => styleIndex.get(id),
    getCard: (id) => cardIndex.get(id),
    findCards(styleId, filter = {}) {
      return (styleIndex.get(styleId)?.cards ?? []).filter(
        (card) =>
          (filter.tier === undefined || card.tier === filter.tier) &&
          (filter.purpose === undefined || card.purpose === filter.purpose),
      );
    },
  };
}

/** One card as producer sessions see it when choosing cards for a storyboard. */
export interface CatalogueEntry {
  id: string;
  tier: string;
  purpose: string;
  slots: { name: string; type: SlotType; maxChars: number }[];
  durationSec: { min: number; max: number };
}

/** The compact card catalogue of one style, for a storyboarding prompt. */
export function cardCatalogue(registry: CardRegistry, styleId: string): CatalogueEntry[] {
  return registry.findCards(styleId).map((card) => ({
    id: card.id,
    tier: card.tier,
    purpose: card.purpose,
    slots: card.slots.map(({ name, type, maxChars }) => ({ name, type, maxChars })),
    durationSec: { ...card.duration },
  }));
}
